    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 65-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Long-term casting in extension", "Arthroscopic lysis of adhesions", "Manipulation under anesthesia (MUA)", "Open arthrolysis and synovectomy", "Revision total knee arthroplasty"]'::jsonb, 2, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 64-year-old patient presents with a painful left hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Iliopsoas bursitis", "Periprosthetic joint infection", "Aseptic loosening due to polyethylene wear", "Heterotopic ossification", "Adverse local tissue reaction (ALTR) / Pseudotumor"]'::jsonb, 4, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 89-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["It only occurs after the 3-month postoperative mark", "Associated with early excessive flexion or poor nutrition", "It is a rare complication seen almost exclusively in young patients", "It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used"]'::jsonb, 1, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 68-year-old patient presents with increasing pain in the knee 8 months after a total knee arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)", "Streptococcus pyogenes; Suppressive intravenous antibiotics only", "Staphylococcus aureus; Two-stage exchange arthroplasty", "Cutibacterium acnes; One-stage exchange arthroplasty", "Staphylococcus epidermidis (Coagulase-negative Staph); Two-stage exchange arthroplasty"]'::jsonb, 4, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and can sometimes be managed with Two-stage exchange arthroplasty. Chronic infections are usually due to less virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and require a two-stage exchange.'),
    (v_topic_id, 'A 78-year-old female undergoes a total hip arthroplasty via a standard anterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Extension, abduction, and internal rotation", "Flexion, adduction, and external rotation", "Extension and external rotation", "Flexion, abduction, and external rotation", "Extension and internal rotation"]'::jsonb, 2, 'In a anterior approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Lateral femoral cutaneous nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 62-year-old patient presents with a painful right hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Adverse local tissue reaction (ALTR) / Pseudotumor", "Periprosthetic joint infection", "Heterotopic ossification", "Iliopsoas bursitis", "Aseptic loosening due to polyethylene wear"]'::jsonb, 0, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 71-year-old patient presents with a painful left hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Adverse local tissue reaction (ALTR) / Pseudotumor", "Aseptic loosening due to polyethylene wear", "Heterotopic ossification", "Periprosthetic joint infection", "Iliopsoas bursitis"]'::jsonb, 0, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 66-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Lateral femoral cutaneous nerve", "Superior gluteal nerve", "Sciatic nerve", "Obturator nerve", "Femoral nerve"]'::jsonb, 4, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 81-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["Associated with early excessive flexion or poor nutrition", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "It is a rare complication seen almost exclusively in young patients", "It is completely preventable with prophylactic antibiotics"]'::jsonb, 0, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 75-year-old patient presents 6 months after a posterior-stabilized total knee arthroplasty complaining of a painful catch or ''clunk'' when extending the knee from a flexed position. What is the most likely etiology of this symptom?', '["Polyethylene wear of the patellar button", "Infection with Staphylococcus epidermidis", "Rupture of the patellar tendon", "Fibrous nodule formation at the superior pole of the patella", "Aseptic loosening of the tibial component"]'::jsonb, 3, 'Patellar clunk syndrome occurs in some posterior-stabilized TKAs when a fibrous nodule forms at the superior pole of the patella. As the knee extends, this nodule catches in the intercondylar box of the femoral component and then pops out with a painful ''''clunk''''.'),
    (v_topic_id, 'A 66-year-old patient presents 6 months after a posterior-stabilized total knee arthroplasty complaining of a painful catch or ''clunk'' when extending the knee from a flexed position. What is the most likely etiology of this symptom?', '["Aseptic loosening of the tibial component", "Polyethylene wear of the patellar button", "Rupture of the patellar tendon", "Fibrous nodule formation at the superior pole of the patella", "Infection with Staphylococcus epidermidis"]'::jsonb, 3, 'Patellar clunk syndrome occurs in some posterior-stabilized TKAs when a fibrous nodule forms at the superior pole of the patella. As the knee extends, this nodule catches in the intercondylar box of the femoral component and then pops out with a painful ''''clunk''''.'),
    (v_topic_id, 'A 56-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Long-term casting in extension", "Arthroscopic lysis of adhesions", "Manipulation under anesthesia (MUA)", "Open arthrolysis and synovectomy", "Revision total knee arthroplasty"]'::jsonb, 2, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 68-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["A patient with marked, uncorrectable varus deformity of the hindfoot", "A patient with a history of deep soft-tissue infection in the affected ankle", "An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A patient with severe avascular necrosis of the talus", "A young, high-demand laborer with a physically strenuous job"]'::jsonb, 2, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 85-year-old patient presents with severe shoulder pain and limited range of motion. Imaging and clinical evaluation confirm massive irreparable rotator cuff tear with pseudoparalysis (cuff tear arthropathy). Which of the following is the most appropriate surgical intervention?', '["Reverse Total Shoulder Arthroplasty (rTSA)", "Arthroscopic debridement and subacromial decompression", "Anatomic Total Shoulder Arthroplasty (TSA)", "Arthrodesis", "Hemiarthroplasty"]'::jsonb, 0, 'The primary indication for Reverse Total Shoulder Arthroplasty (rTSA) is massive irreparable rotator cuff tear with pseudoparalysis (cuff tear arthropathy). Anatomic TSA relies on an intact rotator cuff to maintain the humeral head centered on the glenoid. In contrast, rTSA is designed for cuffs that are severely deficient, utilizing the deltoid muscle to substitute for the rotator cuff.'),
    (v_topic_id, 'A 81-year-old female undergoes a total hip arthroplasty via a standard posterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Flexion, abduction, and external rotation", "Extension, abduction, and internal rotation", "Extension and internal rotation", "Flexion, adduction, and external rotation", "Flexion, adduction, and internal rotation"]'::jsonb, 4, 'In a posterior approach to the hip, the typical position of instability causing dislocation is flexion, adduction, and internal rotation. The Sciatic nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 63-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Placing the femoral component in varus", "Excessive resection of the femoral neck", "Maximizing soft tissue tension to prevent dislocation", "Aggressive reaming of the acetabulum", "Using a smaller femoral head size"]'::jsonb, 2, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 63-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["A patient with marked, uncorrectable varus deformity of the hindfoot", "A patient with a history of deep soft-tissue infection in the affected ankle", "A patient with severe avascular necrosis of the talus", "An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A young, high-demand laborer with a physically strenuous job"]'::jsonb, 3, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 86-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding delirium, which of the following is most accurate in this setting?', '["It only occurs after the 3-month postoperative mark", "It is completely preventable with prophylactic antibiotics", "Common in elderly patients, associated with narcotic use and hypoxia", "It is a rare complication seen almost exclusively in young patients", "It is solely caused by the type of implant bearing surface used"]'::jsonb, 2, 'Delirium is a known systemic complication following major joint arthroplasty. Specifically, it is common in elderly patients, associated with narcotic use and hypoxia. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 70-year-old patient presents with severe shoulder pain and limited range of motion. Imaging and clinical evaluation confirm severe 4-part proximal humerus fracture in an 80-year-old. Which of the following is the most appropriate surgical intervention?', '["Reverse Total Shoulder Arthroplasty (rTSA)", "Arthrodesis", "Hemiarthroplasty", "Arthroscopic debridement and subacromial decompression", "Anatomic Total Shoulder Arthroplasty (TSA)"]'::jsonb, 0, 'The primary indication for Reverse Total Shoulder Arthroplasty (rTSA) is severe 4-part proximal humerus fracture in an 80-year-old. Anatomic TSA relies on an intact rotator cuff to maintain the humeral head centered on the glenoid. In contrast, rTSA is designed for cuffs that are severely deficient, utilizing the deltoid muscle to substitute for the rotator cuff.'),
    (v_topic_id, 'A 78-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "Associated with early excessive flexion or poor nutrition", "It is a rare complication seen almost exclusively in young patients"]'::jsonb, 3, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 76-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Sciatic nerve", "Superior gluteal nerve", "Lateral femoral cutaneous nerve", "Obturator nerve", "Femoral nerve"]'::jsonb, 4, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 74-year-old patient presents with increasing pain in the shoulder 8 months after a total shoulder arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Cutibacterium acnes; One-stage exchange arthroplasty", "Staphylococcus epidermidis (Coagulase-negative Staph); Two-stage exchange arthroplasty", "Staphylococcus aureus; Two-stage exchange arthroplasty", "Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)", "Streptococcus pyogenes; Suppressive intravenous antibiotics only"]'::jsonb, 1, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and can sometimes be managed with Two-stage exchange arthroplasty. Chronic infections are usually due to less virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and require a two-stage exchange.'),
    (v_topic_id, 'A 82-year-old patient presents with increasing pain in the hip 3 weeks after a total hip arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)", "Staphylococcus aureus; Two-stage exchange arthroplasty", "Staphylococcus aureus; Debridement, antibiotics, and implant retention (DAIR)", "Streptococcus pyogenes; Suppressive intravenous antibiotics only", "Cutibacterium acnes; One-stage exchange arthroplasty"]'::jsonb, 2, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus aureus and can sometimes be managed with Debridement, antibiotics, and implant retention (DAIR). Chronic infections are usually due to less virulent organisms like Staph epidermidis and require a two-stage exchange.'),
    (v_topic_id, 'A 80-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding wound dehiscence, which of the following is most accurate in this setting?', '["It is completely preventable with prophylactic antibiotics", "Associated with early excessive flexion or poor nutrition", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "It is a rare complication seen almost exclusively in young patients"]'::jsonb, 1, 'Wound dehiscence is a known systemic complication following major joint arthroplasty. Specifically, it is associated with early excessive flexion or poor nutrition. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 70-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Staphylococcus aureus", "Streptococcus pyogenes", "Cutibacterium acnes", "Pseudomonas aeruginosa", "Staphylococcus epidermidis"]'::jsonb, 2, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 90-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding delirium, which of the following is most accurate in this setting?', '["It is completely preventable with prophylactic antibiotics", "Common in elderly patients, associated with narcotic use and hypoxia", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "It is a rare complication seen almost exclusively in young patients"]'::jsonb, 1, 'Delirium is a known systemic complication following major joint arthroplasty. Specifically, it is common in elderly patients, associated with narcotic use and hypoxia. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 64-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Staphylococcus epidermidis", "Pseudomonas aeruginosa", "Streptococcus pyogenes", "Staphylococcus aureus", "Cutibacterium acnes"]'::jsonb, 4, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 80-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Trochanteric region. This is classified as Vancouver A. What is the most appropriate management?', '["Nonoperative or cerclage wires if widely displaced", "ORIF with plates and cables", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with a longer stem", "Revision arthroplasty with proximal femoral replacement"]'::jsonb, 0, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver A fractures occur Trochanteric region and are best managed by Nonoperative or cerclage wires if widely displaced.'),
